hooks.command:
cmd=$(jq -r '.tool_input.command // ""'); printf '%s' "$cmd" | grep -qE 'git[[:space:]]+commit' || exit 0; root=$(git rev-parse --show-toplevel) || exit 0; out=$(cd "$root" && uv run ruff check . && uv run ruff format --check . && uv run mypy skills/zilliz-launchpad/scripts && uv run pytest -m "not cloud and not e2e and not multimodal and not documents" 2>&1) || { printf 'Pre-commit checks failed. Fix the issues below, then commit again (git commit will re-run these checks):

%s
' "$out" >&2; exit 2; }
